export const $=id=>document.getElementById(id);
export function el(tag,className,text){const n=document.createElement(tag);if(className)n.className=className;if(text!==undefined)n.textContent=text;return n;}
let timer;
export function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(timer);timer=setTimeout(()=>$('toast').hidden=true,5200);}
export function localRead(key,fallback){try{const v=localStorage.getItem(key);return v===null?fallback:JSON.parse(v);}catch{return fallback;}}
export function localWrite(key,value){try{localStorage.setItem(key,JSON.stringify(value));}catch{throw new Error('浏览器不允许本机存储，未保存到本机；请导出备份或检查设置。');}}
export function dateLabel(value,short=false){if(!value)return '—';const d=new Date(value);if(!Number.isFinite(d.valueOf()))return '—';return new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',...(short?{hour:'2-digit',minute:'2-digit',hour12:false}:{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false})}).format(d);}
export async function copyText(text){if(!text)throw new Error('没有可复制的内容。');try{await navigator.clipboard.writeText(text);return;}catch{}const t=el('textarea');t.value=text;t.style.position='fixed';t.style.left='-9999px';document.body.append(t);t.select();let ok=false;try{ok=document.execCommand('copy');}finally{t.remove();}if(!ok)throw new Error('浏览器未允许自动复制，请手动选中内容复制。');}
export function download(text,name,type='text/plain;charset=utf-8'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000);}
export function action(button,fn){button.addEventListener('click',event=>{Promise.resolve().then(()=>fn(event)).catch(e=>toast(e.message||'操作失败。'));});}
export function confirmAction(message){return new Promise(resolve=>{const dialog=el('dialog'),title=el('h2',null,'确认操作'),body=el('p','muted',message),buttons=el('div','actions'),cancel=el('button','button outline','取消'),ok=el('button','button primary','继续');dialog.setAttribute('aria-label','确认操作');cancel.type=ok.type='button';cancel.addEventListener('click',()=>dialog.close('cancel'));ok.addEventListener('click',()=>dialog.close('ok'));buttons.append(cancel,ok);dialog.append(title,body,buttons);dialog.addEventListener('close',()=>{const yes=dialog.returnValue==='ok';dialog.remove();resolve(yes);},{once:true});document.body.append(dialog);dialog.showModal();});}
